def is_kenyan_mobile(s):
    s = s.replace(" ", "")
    return (len(s) == 10 and s.startswith(("07", "01")) and s.isdigit()) or (len(s) == 13 and s.startswith(("+2547", "+2541")) and s[1:].isdigit())
